diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..5ad031d 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -178,6 +178,48 @@ assert.equal(missionUnknown.receipt_status, 'unknown');
 assert.equal(missionUnknown.cost, null);
 assert.equal(missionUnknown.cost_status, 'unknown');

+// Adversarial substitution: the run was billed as one model and reports another
+// under trusted telemetry. A verified receipt binds the profile, not the model,
+// so it must never launder the mismatch into a pass, and the telemetry the
+// substituted observation omits stays unknown rather than inferred or zeroed.
+const substituted = Object.freeze({ model: codex.model, trusted: true, source: 'codex-session-jsonl' });
+assert.deepEqual(profiles.evaluateModelProof(local, substituted), {
+  requested_model: local.model, observed_model: codex.model, status: 'failed',
+  reason_code: 'MODEL_OBSERVATION_MISMATCH',
+});
+// Matching is exact: neither case folding nor a prefix or suffix may pass.
+for (const observed of ['QWEN3-CODER:30B', 'qwen3-coder', 'qwen3-coder:30b-instruct']) {
+  const nearMiss = profiles.evaluateModelProof(local, { model: observed, trusted: true });
+  assert.equal(nearMiss.status, 'failed', observed);
+  assert.equal(nearMiss.observed_model, observed, observed);
+}
+
+const substitutedVerification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+const missionSubstituted = profiles.missionControlExecutorState({
+  profile: local, observation: substituted, wrapper, verification: substitutedVerification,
+});
+assert.equal(missionSubstituted.receipt_status, 'verified');
+assert.equal(missionSubstituted.requested_model, local.model);
+assert.equal(missionSubstituted.observed_model, codex.model);
+assert.equal(missionSubstituted.model_status, 'failed');
+assert.equal(missionSubstituted.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.deepEqual([missionSubstituted.cost, missionSubstituted.duration_ms, missionSubstituted.tokens],
+  [null, null, null], 'missing telemetry must not be inferred or zeroed');
+assert.deepEqual([missionSubstituted.cost_status, missionSubstituted.duration_status, missionSubstituted.tokens_status],
+  ['unknown', 'unknown', 'unknown']);
+
+const substitutedReplay = profiles.publicExecutorReplay({
+  profile: local, observation: substituted, wrapper, verification: substitutedVerification,
+});
+assert.equal(substitutedReplay.model_status, 'failed');
+assert.equal(substitutedReplay.model_reason_code, 'MODEL_OBSERVATION_MISMATCH');
+assert.equal(substitutedReplay.requested_model, local.model);
+assert.equal(substitutedReplay.observed_model, codex.model,
+  'public replay must show the substituted model, not hide it');
+assert.equal(substitutedReplay.receipt_status, 'verified');
+assert.deepEqual([substitutedReplay.cost_status, substitutedReplay.duration_status, substitutedReplay.tokens_status],
+  ['unknown', 'unknown', 'unknown']);
+
 const replay = profiles.publicExecutorReplay({ profile: local, observation: null, wrapper });
 const serialized = JSON.stringify(replay);
 for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command', 'args']) {
